// Verification against cases whose answer is known without running the code.
//
// Pre-registered risk: if the synthetic data is generated by the same model
// being fitted, everything fits and the tests prove nothing. So the decisive
// case is #3 — a stock that moved hugely for a reason the model should explain
// away. A flat-percentage check flags it; a residual check must not.

import {
  fitFactorModel, residualZ, pricedInVerdict, exitVerdict, logReturns,
} from "../src/market/residual.mjs";

let seed = 42;
const rand = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const noise = (s) => (rand() - 0.5) * 2 * s;

const N = 250;
const market = Array.from({ length: N }, () => noise(0.01));
const sector = market.map((m) => 1.2 * m + noise(0.006));

let failed = 0;
const check = (name, pass, detail) => {
  if (!pass) failed++;
  console.log(`${pass ? "PASS" : "FAIL"}  ${name}\n        ${detail}`);
};

// 1 — a stock that is pure beta has almost no idiosyncratic residual.
{
  const asset = market.map((m, i) => 1.5 * m + 0.3 * (sector[i] - 1.2 * m));
  const model = fitFactorModel({ asset, market, sector });
  check("pure-beta stock recovers its betas",
    model.ok && Math.abs(model.betaMarket - 1.5) < 0.05 && model.residualSigma < 1e-8,
    `betaMarket=${model.betaMarket?.toFixed(3)} residualSigma=${model.residualSigma?.toExponential(2)}`);
}

// 2 — a known idiosyncratic shock shows up at roughly its size in sigmas.
{
  const asset = market.map((m, i) => 1.5 * m + 0.3 * (sector[i] - 1.2 * m) + noise(0.008));
  const model = fitFactorModel({ asset, market, sector });
  const shock = 3 * model.residualSigma;
  const r = residualZ(model, {
    assetReturn: 1.5 * 0.004 + shock, marketReturn: 0.004, sectorReturn: 1.2 * 0.004, periods: 1,
  });
  check("a 3σ idiosyncratic shock scores ≈3σ",
    r.ok && Math.abs(r.z - 3) < 0.25, `z=${r.z.toFixed(2)}`);
}

// 3 — THE decisive case. Stock is up 7.5% but only because the market is up 5%.
//     A flat "moved more than 6%, too late" rule discards this name. The
//     residual check must see through it and call it unmoved.
{
  const asset = market.map((m, i) => 1.5 * m + 0.3 * (sector[i] - 1.2 * m) + noise(0.008));
  const model = fitFactorModel({ asset, market, sector });
  const marketReturn = 0.05;
  const r = residualZ(model, {
    assetReturn: 1.5 * marketReturn, marketReturn, sectorReturn: 1.2 * marketReturn, periods: 1,
  });
  const v = pricedInVerdict(r.z, +1);
  check("a big move fully explained by the market is still UNPRICED",
    r.ok && Math.abs(r.z) < 1 && v.state === "unpriced",
    `assetReturn=+7.5% z=${r.z.toFixed(2)} -> ${v.state} ("${v.reason}")`);
}

// 4 — direction matters: a move against the thesis is not "priced in".
{
  check("move against the thesis is contradicted, not priced",
    pricedInVerdict(-2.5, +1).state === "contradicted" && pricedInVerdict(2.5, +1).state === "priced",
    `z=-2.5 -> ${pricedInVerdict(-2.5, +1).state}; z=+2.5 -> ${pricedInVerdict(2.5, +1).state}`);
  check("short thesis reads the sign the other way",
    pricedInVerdict(-2.5, -1).state === "priced" && pricedInVerdict(0.4, -1).tradeable === true,
    `short: z=-2.5 -> ${pricedInVerdict(-2.5, -1).state}, z=+0.4 -> ${pricedInVerdict(0.4, -1).state}`);
}

// 5 — multi-day windows are scaled by √periods, not judged on a 1-day yardstick.
{
  const asset = market.map((m, i) => 1.0 * m + noise(0.008));
  const model = fitFactorModel({ asset, market });
  const one = residualZ(model, { assetReturn: 0.02, marketReturn: 0, periods: 1 });
  const four = residualZ(model, { assetReturn: 0.02, marketReturn: 0, periods: 4 });
  // The claim is that the yardstick grows with sqrt(periods). The z-ratio is
  // not exactly 2 because expected drift (alpha) also scales with periods —
  // conflating those two was an error in the assertion, not in the model.
  check("the yardstick scales with sqrt(periods)",
    Math.abs(four.scale / one.scale - 2) < 1e-9,
    `scale1=${one.scale.toExponential(3)} scale4=${four.scale.toExponential(3)} ratio=${(four.scale / one.scale).toFixed(6)}`);
  const sameResidualZ4 = one.residual / four.scale;
  check("an identical residual scores half the z over 4 periods",
    Math.abs(one.z / sameResidualZ4 - 2) < 1e-9,
    `z(1p)=${one.z.toFixed(3)} vs same residual over 4p=${sameResidualZ4.toFixed(3)}`);
}

// 6 — guards fire rather than returning a confident wrong number.
{
  const short = fitFactorModel({ asset: [0.01, 0.02], market: [0.01, 0.02] });
  const flat = fitFactorModel({ asset: Array(80).fill(0.001), market: Array(80).fill(0) });
  check("insufficient history refuses to fit", !short.ok, short.reason);
  check("zero market variance refuses to fit", !flat.ok, flat.reason);
}

// 7 — exit trigger is the same statistic.
{
  check("exit fires when the residual arrives",
    exitVerdict(2.2, +1).exit === true && exitVerdict(0.8, +1).exit === false,
    `z=2.2 -> "${exitVerdict(2.2, +1).reason}"; z=0.8 -> "${exitVerdict(0.8, +1).reason}"`);
}

// 8 — log returns aggregate additively across a window.
{
  const closes = [100, 102, 101, 105];
  const rs = logReturns(closes);
  const total = rs.reduce((a, b) => a + b, 0);
  check("log returns sum to the whole-window return",
    Math.abs(total - Math.log(105 / 100)) < 1e-12, `Σr=${total.toFixed(6)} log(105/100)=${Math.log(1.05).toFixed(6)}`);
}

console.log(`\n${failed ? failed + " FAILED" : "all passed"}`);
process.exit(failed ? 1 : 0);
